import sys
from collections import defaultdict, deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    edges = []
    adj = defaultdict(list)
    rev_adj = defaultdict(list)

    for i in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        edges.append((u, v))
        adj[u].append(v)
        rev_adj[v].append(u)

    dist = [-1] * (n + 1)
    dist[1] = 0
    q = deque([1])

    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)
            else:
                pass

    if dist[n] == -1:
        print("No")
        return

    ans = [0] * m
    possible = True

    for i in range(m):
        u, v = edges[i]
        if dist[u] == -1 or dist[v] == -1:
            continue

        diff = dist[v] - dist[u]
        if diff == 1:
            ans[i] = 1
        elif diff == 2:
            ans[i] = 2
        else:
            possible = False
            break

    if not possible:
        print("No")
        return

    target_dist = dist[n]

    dp = {}
    dp[1] = {0}

    order = []
    q = deque([1])
    visited = set([1])
    while q:
        u = q.popleft()
        order.append(u)
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                q.append(v)

    for u in order:
        if u not in dp:
            continue
        for v in adj[u]:
            if v not in dp:
                dp[v] = set()
            for d in dp[u]:
                if (v, u) in [(e[1], e[0]) for e in edges]:
                    idx = -1
                    for k in range(m):
                        if edges[k] == (u, v):
                            idx = k
                            break
                    w = ans[idx]
                    dp[v].add(d + w)

    if n not in dp or len(dp[n]) != 1:
        print("No")
        return

    print("Yes")
    for x in ans:
        print(x)

if __name__ == "__main__":
    solve()
